using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve the old property name so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonProperty("Discriminator");

        // Breaking change 2: id format changed from "EntityType|Key" to just "Key".
        // Preserve the old format so existing documents (e.g. "Blog|1") are still found.
        modelBuilder.Entity<Blog>().HasIdProperty(b => b.Id)
            .HasIdJsonProperty("id");
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasValueGeneratorFactory<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGeneratorFactory>();

        // Breaking change 3: HasIndex now throws for Cosmos. Remove or suppress it.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); -- removed
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Opt-in to the legacy id format ("EntityType|Key") for all entities.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.IdValueGeneratorConvention());
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

